import { useState, useCallback, useEffect } from "react";
import type { HeadersFunction, LoaderFunctionArgs } from "react-router";
import { useNavigate } from "react-router";
import {
  Page,
  Layout,
  Card,
  Text,
  InlineStack,
  BlockStack,
  Badge,
  Button,
  Box,
  Divider,
  IndexTable,
  Modal,
  EmptyState,
  useIndexResourceState,
  ButtonGroup,
} from "@shopify/polaris";
import { useAppBridge } from "@shopify/app-bridge-react";
import { authenticate } from "../shopify.server";
import { boundary } from "@shopify/shopify-app-react-router/server";

// --- Mock Data ---

const quizzes = [
  {
    id: "1",
    name: "Skincare Routine Finder",
    emoji: "\uD83E\uDDF4",
    subtitle: "Beauty collection",
    status: "Live" as const,
    questions: 8,
    completions: 842,
    convRate: "22.1%",
    revenue: "$8,320",
    updated: "Mar 22, 2026",
  },
  {
    id: "2",
    name: "Gift Guide Quiz",
    emoji: "\uD83C\uDF81",
    subtitle: "Holiday campaign",
    status: "Draft" as const,
    questions: 5,
    completions: 0,
    convRate: "0%",
    revenue: "$0",
    updated: "Mar 20, 2026",
  },
  {
    id: "3",
    name: "Coffee Preference Quiz",
    emoji: "\u2615",
    subtitle: "Beverages collection",
    status: "Archived" as const,
    questions: 6,
    completions: 405,
    convRate: "14.8%",
    revenue: "$4,130",
    updated: "Feb 15, 2026",
  },
];

const statusToneMap: Record<string, "success" | "attention" | undefined> = {
  Live: "success",
  Draft: "attention",
  Archived: undefined,
};

const templates = [
  {
    id: "skincare",
    name: "Skincare Finder",
    emoji: "\uD83E\uDDF4",
    category: "Beauty, Wellness",
    questions: 5,
    types: "Single choice, Image choice, Multiple select, Slider, Email capture",
    badge: "Popular" as const,
  },
  {
    id: "supplement",
    name: "Supplement Advisor",
    emoji: "\uD83D\uDC8A",
    category: "Health, Fitness",
    questions: 4,
    types: "Single choice, Yes/No, Multiple select, Email capture",
    badge: "New" as const,
  },
  {
    id: "style",
    name: "Style Finder",
    emoji: "\uD83D\uDC57",
    category: "Apparel, Fashion",
    questions: 4,
    types: "Image choice, Single choice, Dropdown, Email capture",
    badge: null,
  },
  {
    id: "haircare",
    name: "Hair Care Match",
    emoji: "\uD83D\uDC87",
    category: "Hair, Beauty",
    questions: 4,
    types: "Single choice, Dropdown, Slider, Email capture",
    badge: null,
  },
  {
    id: "fitness",
    name: "Fitness Advisor",
    emoji: "\uD83C\uDFCB\uFE0F",
    category: "Sports, Health",
    questions: 5,
    types: "Single choice, Multiple select, Slider, Yes/No, Email capture",
    badge: null,
  },
  {
    id: "blank",
    name: "Start from blank",
    emoji: "\u2795",
    category: "Custom",
    questions: 0,
    types: "Manual",
    badge: null,
  },
];

const progressSteps = [
  "Reading product catalogue...",
  "Generating questions & answers...",
  "Mapping products to answers...",
  "Finalising your quiz...",
];

// --- Loader ---

export const loader = async ({ request }: LoaderFunctionArgs) => {
  await authenticate.admin(request);
  return null;
};

// --- Components ---

function TemplateCard({
  template,
  onSelect,
}: {
  template: (typeof templates)[0];
  onSelect: (id: string) => void;
}) {
  const badgeTone =
    template.badge === "Popular"
      ? "success"
      : template.badge === "New"
        ? "info"
        : undefined;

  return (
    <div
      style={{
        cursor: "pointer",
        border: "1px solid var(--p-color-border)",
        borderRadius: "var(--p-border-radius-300)",
        padding: "16px",
        transition: "box-shadow 0.15s ease",
        height: "100%",
      }}
      onClick={() => onSelect(template.id)}
      onMouseEnter={(e) => {
        (e.currentTarget as HTMLElement).style.boxShadow =
          "0 0 0 2px var(--p-color-border-emphasis)";
      }}
      onMouseLeave={(e) => {
        (e.currentTarget as HTMLElement).style.boxShadow = "none";
      }}
      role="button"
      tabIndex={0}
      onKeyDown={(e) => {
        if (e.key === "Enter" || e.key === " ") {
          e.preventDefault();
          onSelect(template.id);
        }
      }}
    >
      <BlockStack gap="300">
        <InlineStack align="space-between" blockAlign="start">
          <Text as="span" variant="headingXl">
            {template.emoji}
          </Text>
          {template.badge && (
            <Badge tone={badgeTone}>{template.badge}</Badge>
          )}
        </InlineStack>
        <BlockStack gap="100">
          <Text as="p" variant="headingSm" fontWeight="semibold">
            {template.name}
          </Text>
          <InlineStack gap="100">
            {template.category.split(", ").map((cat) => (
              <Badge key={cat} tone="info">
                {cat}
              </Badge>
            ))}
          </InlineStack>
        </BlockStack>
        <Text as="p" variant="bodySm" tone="subdued">
          {template.questions === 0
            ? "No pre-built questions"
            : `${template.questions} questions`}
        </Text>
      </BlockStack>
    </div>
  );
}

function AIGenerationOverlay({
  onComplete,
}: {
  onComplete: () => void;
}) {
  const [currentStep, setCurrentStep] = useState(0);
  const [completedSteps, setCompletedSteps] = useState<number[]>([]);

  useEffect(() => {
    const timers: ReturnType<typeof setTimeout>[] = [];

    progressSteps.forEach((_, index) => {
      const timer = setTimeout(() => {
        setCurrentStep(index);
        if (index > 0) {
          setCompletedSteps((prev) => [...prev, index - 1]);
        }
      }, index * 750);
      timers.push(timer);
    });

    // Mark last step complete and navigate
    const finalTimer = setTimeout(() => {
      setCompletedSteps((prev) => [...prev, progressSteps.length - 1]);
    }, progressSteps.length * 750);
    timers.push(finalTimer);

    const navTimer = setTimeout(() => {
      onComplete();
    }, progressSteps.length * 750 + 500);
    timers.push(navTimer);

    return () => timers.forEach(clearTimeout);
  }, [onComplete]);

  return (
    <div
      style={{
        position: "fixed",
        inset: 0,
        zIndex: 9999,
        background: "rgba(255, 255, 255, 0.97)",
        display: "flex",
        alignItems: "center",
        justifyContent: "center",
      }}
    >
      <div style={{ textAlign: "center", maxWidth: 420 }}>
        <div
          style={{
            width: 64,
            height: 64,
            margin: "0 auto 24px",
            border: "4px solid var(--p-color-border)",
            borderTopColor: "var(--p-color-border-emphasis)",
            borderRadius: "50%",
            animation: "quizsnap-spin 0.8s linear infinite",
          }}
        />
        <style>
          {`@keyframes quizsnap-spin { to { transform: rotate(360deg); } }`}
        </style>
        <BlockStack gap="200">
          <Text as="p" variant="headingLg" fontWeight="bold">
            Building your quiz with AI...
          </Text>
          <Text as="p" variant="bodySm" tone="subdued">
            This usually takes a few seconds
          </Text>
        </BlockStack>
        <div style={{ marginTop: 32, textAlign: "left" }}>
          <BlockStack gap="300">
            {progressSteps.map((step, index) => {
              const isCompleted = completedSteps.includes(index);
              const isCurrent = currentStep === index && !isCompleted;
              return (
                <InlineStack key={index} gap="300" blockAlign="center">
                  <div
                    style={{
                      width: 24,
                      height: 24,
                      borderRadius: "50%",
                      display: "flex",
                      alignItems: "center",
                      justifyContent: "center",
                      fontSize: 14,
                      background: isCompleted
                        ? "var(--p-color-bg-fill-success)"
                        : isCurrent
                          ? "var(--p-color-bg-fill-emphasis)"
                          : "var(--p-color-bg-surface-secondary)",
                      color: isCompleted || isCurrent ? "#fff" : "var(--p-color-text-subdued)",
                      flexShrink: 0,
                    }}
                  >
                    {isCompleted ? "\u2713" : index + 1}
                  </div>
                  <Text
                    as="p"
                    variant="bodyMd"
                    tone={isCompleted ? "success" : isCurrent ? undefined : "subdued"}
                    fontWeight={isCurrent ? "semibold" : "regular"}
                  >
                    {step}
                  </Text>
                </InlineStack>
              );
            })}
          </BlockStack>
        </div>
      </div>
    </div>
  );
}

// --- Main Page ---

export default function MyQuizzes() {
  const navigate = useNavigate();
  const shopify = useAppBridge();

  const [modalOpen, setModalOpen] = useState(false);
  const [showAIOverlay, setShowAIOverlay] = useState(false);
  const [selectedTemplate, setSelectedTemplate] = useState<string | null>(null);
  const [showEmptyState] = useState(false); // Toggle to true to see empty state

  const handleOpenModal = useCallback(() => {
    setModalOpen(true);
  }, []);

  const handleCloseModal = useCallback(() => {
    setModalOpen(false);
  }, []);

  const handleSelectTemplate = useCallback(
    (templateId: string) => {
      setSelectedTemplate(templateId);
      setModalOpen(false);

      if (templateId === "blank") {
        navigate("/app/quizzes/new");
      } else {
        setShowAIOverlay(true);
      }
    },
    [navigate],
  );

  const handleAIComplete = useCallback(() => {
    setShowAIOverlay(false);
    shopify.toast.show("Quiz created successfully!");
    navigate(`/app/quizzes/new?template=${selectedTemplate}`);
  }, [navigate, selectedTemplate, shopify]);

  const handleEditQuiz = useCallback(
    (id: string) => {
      navigate(`/app/quizzes/${id}`);
    },
    [navigate],
  );

  const handlePreviewQuiz = useCallback(
    (id: string) => {
      navigate(`/app/quizzes/${id}/preview`);
    },
    [navigate],
  );

  const handleArchiveQuiz = useCallback(
    (id: string) => {
      shopify.toast.show(`Quiz ${id} archived`);
    },
    [shopify],
  );

  const resourceName = { singular: "quiz", plural: "quizzes" };
  const { selectedResources, allResourcesSelected, handleSelectionChange } =
    useIndexResourceState(quizzes);

  const rowMarkup = quizzes.map(
    (
      {
        id,
        name,
        emoji,
        subtitle,
        status,
        questions,
        completions,
        convRate,
        revenue,
        updated,
      },
      index,
    ) => (
      <IndexTable.Row
        id={id}
        key={id}
        selected={selectedResources.includes(id)}
        position={index}
      >
        <IndexTable.Cell>
          <InlineStack gap="300" blockAlign="center">
            <Text as="span" variant="headingMd">
              {emoji}
            </Text>
            <BlockStack gap="050">
              <Text as="span" variant="bodyMd" fontWeight="semibold">
                {name}
              </Text>
              <Text as="span" variant="bodySm" tone="subdued">
                {subtitle}
              </Text>
            </BlockStack>
          </InlineStack>
        </IndexTable.Cell>
        <IndexTable.Cell>
          <Badge tone={statusToneMap[status]}>{status}</Badge>
        </IndexTable.Cell>
        <IndexTable.Cell>
          <Text as="span" variant="bodyMd" alignment="end">
            {questions}
          </Text>
        </IndexTable.Cell>
        <IndexTable.Cell>
          <Text as="span" variant="bodyMd" alignment="end">
            {completions.toLocaleString()}
          </Text>
        </IndexTable.Cell>
        <IndexTable.Cell>
          <Text as="span" variant="bodyMd" alignment="end">
            {convRate}
          </Text>
        </IndexTable.Cell>
        <IndexTable.Cell>
          <Text as="span" variant="bodyMd" alignment="end">
            {revenue}
          </Text>
        </IndexTable.Cell>
        <IndexTable.Cell>
          <Text as="span" variant="bodySm" tone="subdued">
            {updated}
          </Text>
        </IndexTable.Cell>
        <IndexTable.Cell>
          <ButtonGroup>
            <Button size="slim" onClick={() => handleEditQuiz(id)}>
              Edit
            </Button>
            <Button
              size="slim"
              variant="plain"
              onClick={() => handlePreviewQuiz(id)}
            >
              Preview
            </Button>
            <Button
              size="slim"
              variant="plain"
              tone="critical"
              onClick={() => handleArchiveQuiz(id)}
            >
              Archive
            </Button>
          </ButtonGroup>
        </IndexTable.Cell>
      </IndexTable.Row>
    ),
  );

  return (
    <>
      {showAIOverlay && <AIGenerationOverlay onComplete={handleAIComplete} />}

      <Page
        title="My Quizzes"
        primaryAction={{
          content: "+ Create quiz",
          onAction: handleOpenModal,
        }}
      >
        <BlockStack gap="600">
          {showEmptyState ? (
            <Card>
              <EmptyState
                heading="Create your first quiz"
                action={{
                  content: "Create quiz",
                  onAction: handleOpenModal,
                }}
                image="https://cdn.shopify.com/s/files/1/0262/4071/2726/files/emptystate-files.png"
              >
                <p>
                  Build product recommendation quizzes that help your customers
                  find the perfect product and boost your sales.
                </p>
              </EmptyState>
            </Card>
          ) : (
            <Layout>
              <Layout.Section>
                <Card padding="0">
                  <BlockStack>
                    <Box padding="400">
                      <InlineStack align="space-between" blockAlign="center">
                        <Text as="h2" variant="headingMd">
                          All Quizzes
                        </Text>
                        <Text as="p" variant="bodySm" tone="subdued">
                          {quizzes.length} quizzes
                        </Text>
                      </InlineStack>
                    </Box>
                    <IndexTable
                      resourceName={resourceName}
                      itemCount={quizzes.length}
                      selectedItemsCount={
                        allResourcesSelected
                          ? "All"
                          : selectedResources.length
                      }
                      onSelectionChange={handleSelectionChange}
                      headings={[
                        { title: "Quiz" },
                        { title: "Status" },
                        { title: "Questions", alignment: "end" },
                        { title: "Completions", alignment: "end" },
                        { title: "Conv. Rate", alignment: "end" },
                        { title: "Revenue", alignment: "end" },
                        { title: "Updated" },
                        { title: "Actions" },
                      ]}
                    >
                      {rowMarkup}
                    </IndexTable>
                  </BlockStack>
                </Card>
              </Layout.Section>
            </Layout>
          )}
        </BlockStack>
      </Page>

      <Modal open={modalOpen} onClose={handleCloseModal}>
        <Box padding="400">
          <BlockStack gap="400">
            <Text as="h2" variant="headingLg" fontWeight="bold">
              Choose a template
            </Text>
            <Text as="p" variant="bodyMd" tone="subdued">
              Pick a pre-built quiz template or start from scratch
            </Text>
            <Divider />
            <div
              style={{
                display: "grid",
                gridTemplateColumns: "repeat(3, 1fr)",
                gap: "16px",
              }}
            >
              {templates.map((template) => (
                <TemplateCard
                  key={template.id}
                  template={template}
                  onSelect={handleSelectTemplate}
                />
              ))}
            </div>
          </BlockStack>
        </Box>
      </Modal>
    </>
  );
}

export const headers: HeadersFunction = (headersArgs) => {
  return boundary.headers(headersArgs);
};

import { useCallback } from "react";
import type {
  ActionFunctionArgs,
  HeadersFunction,
  LoaderFunctionArgs,
} from "react-router";
import { useNavigate } from "react-router";
import {
  Page,
  Layout,
  Card,
  Text,
  InlineStack,
  BlockStack,
  Banner,
  ProgressBar,
  List,
  IndexTable,
  Badge,
  Button,
  Box,
  Divider,
  useIndexResourceState,
} from "@shopify/polaris";
import { authenticate } from "../shopify.server";
import { boundary } from "@shopify/shopify-app-react-router/server";

// --- Mock Data ---

const stats = {
  revenue: { value: "$12,450", trend: "+23%", up: true },
  completions: { value: "1,247", trend: "+18%", up: true },
  conversionRate: { value: "18.3%", trend: "-2.1%", up: false },
  emailsCaptured: { value: "892", trend: "+31%", up: true },
};

const setupSteps = [
  { label: "Create your first quiz", complete: true },
  { label: "Map products to answers", complete: false },
  { label: "Publish your quiz", complete: false },
];

const quizzes = [
  {
    id: "1",
    name: "Skincare Routine Finder",
    emoji: "\uD83E\uDDF4",
    subtitle: "Beauty collection",
    status: "Live" as const,
    questions: 8,
    completions: 842,
    convRate: "22.1%",
    revenue: "$8,320",
    updated: "Mar 22, 2026",
  },
  {
    id: "2",
    name: "Gift Guide Quiz",
    emoji: "\uD83C\uDF81",
    subtitle: "Holiday campaign",
    status: "Draft" as const,
    questions: 5,
    completions: 0,
    convRate: "0%",
    revenue: "$0",
    updated: "Mar 20, 2026",
  },
  {
    id: "3",
    name: "Coffee Preference Quiz",
    emoji: "\u2615",
    subtitle: "Beverages collection",
    status: "Archived" as const,
    questions: 6,
    completions: 405,
    convRate: "14.8%",
    revenue: "$4,130",
    updated: "Feb 15, 2026",
  },
];

const statusToneMap: Record<string, "success" | "attention" | undefined> = {
  Live: "success",
  Draft: "attention",
  Archived: undefined,
};

// --- Loader / Action ---

export const loader = async ({ request }: LoaderFunctionArgs) => {
  await authenticate.admin(request);
  return null;
};

export const action = async ({ request }: ActionFunctionArgs) => {
  await authenticate.admin(request);
  return null;
};

// --- Components ---

function StatCard({
  label,
  value,
  trend,
  up,
  borderColor,
}: {
  label: string;
  value: string;
  trend: string;
  up: boolean;
  borderColor: string;
}) {
  return (
    <Card>
      <div style={{ borderTop: `3px solid ${borderColor}`, paddingTop: "4px" }}>
        <BlockStack gap="200">
          <Text as="p" variant="bodySm" tone="subdued">
            {label}
          </Text>
          <Text as="p" variant="headingXl" fontWeight="bold">
            {value}
          </Text>
          <Text
            as="p"
            variant="bodySm"
            tone={up ? "success" : "critical"}
          >
            {up ? "\u2191" : "\u2193"} {trend} vs last month
          </Text>
        </BlockStack>
      </div>
    </Card>
  );
}

function SetupChecklist({ onFinish }: { onFinish: () => void }) {
  const completedCount = setupSteps.filter((s) => s.complete).length;
  const totalCount = setupSteps.length;
  const progressPercent = Math.round((completedCount / totalCount) * 100);

  // If all steps are complete, don't show the banner
  if (completedCount === totalCount) return null;

  return (
    <Banner
      title="Complete your setup"
      tone="info"
      action={{ content: "Finish setup \u2192", onAction: onFinish }}
    >
      <BlockStack gap="300">
        <Text as="p" variant="bodySm" tone="subdued">
          {completedCount} of {totalCount} steps completed
        </Text>
        <ProgressBar progress={progressPercent} size="small" tone="primary" />
        <List type="number">
          {setupSteps.map((step, i) => (
            <List.Item key={i}>
              {step.label} {step.complete ? "\u2705" : ""}
            </List.Item>
          ))}
        </List>
      </BlockStack>
    </Banner>
  );
}

// --- Main Page ---

export default function Dashboard() {
  const navigate = useNavigate();

  const handleCreateQuiz = useCallback(() => {
    navigate("/app/quizzes/new");
  }, [navigate]);

  const handleViewAnalytics = useCallback(() => {
    navigate("/app/analytics");
  }, [navigate]);

  const handleFinishSetup = useCallback(() => {
    navigate("/app/quizzes/new");
  }, [navigate]);

  const handleEditQuiz = useCallback(
    (id: string) => {
      navigate(`/app/quizzes/${id}`);
    },
    [navigate],
  );

  const handlePreviewQuiz = useCallback(
    (id: string) => {
      navigate(`/app/quizzes/${id}/preview`);
    },
    [navigate],
  );

  const resourceName = { singular: "quiz", plural: "quizzes" };

  const { selectedResources, allResourcesSelected, handleSelectionChange } =
    useIndexResourceState(quizzes);

  const rowMarkup = quizzes.map(
    (
      {
        id,
        name,
        emoji,
        subtitle,
        status,
        questions,
        completions,
        convRate,
        revenue,
        updated,
      },
      index,
    ) => (
      <IndexTable.Row
        id={id}
        key={id}
        selected={selectedResources.includes(id)}
        position={index}
      >
        <IndexTable.Cell>
          <InlineStack gap="300" blockAlign="center">
            <Text as="span" variant="headingMd">
              {emoji}
            </Text>
            <BlockStack gap="050">
              <Text as="span" variant="bodyMd" fontWeight="semibold">
                {name}
              </Text>
              <Text as="span" variant="bodySm" tone="subdued">
                {subtitle}
              </Text>
            </BlockStack>
          </InlineStack>
        </IndexTable.Cell>
        <IndexTable.Cell>
          <Badge tone={statusToneMap[status]}>{status}</Badge>
        </IndexTable.Cell>
        <IndexTable.Cell>
          <Text as="span" variant="bodyMd" alignment="end">
            {questions}
          </Text>
        </IndexTable.Cell>
        <IndexTable.Cell>
          <Text as="span" variant="bodyMd" alignment="end">
            {completions.toLocaleString()}
          </Text>
        </IndexTable.Cell>
        <IndexTable.Cell>
          <Text as="span" variant="bodyMd" alignment="end">
            {convRate}
          </Text>
        </IndexTable.Cell>
        <IndexTable.Cell>
          <Text as="span" variant="bodyMd" alignment="end">
            {revenue}
          </Text>
        </IndexTable.Cell>
        <IndexTable.Cell>
          <Text as="span" variant="bodySm" tone="subdued">
            {updated}
          </Text>
        </IndexTable.Cell>
        <IndexTable.Cell>
          <InlineStack gap="200">
            <Button size="slim" onClick={() => handleEditQuiz(id)}>
              Edit
            </Button>
            <Button size="slim" variant="plain" onClick={() => handlePreviewQuiz(id)}>
              Preview
            </Button>
          </InlineStack>
        </IndexTable.Cell>
      </IndexTable.Row>
    ),
  );

  return (
    <Page
      title="Dashboard"
      subtitle="Welcome to QuizSnap"
      primaryAction={{
        content: "+ Create quiz",
        onAction: handleCreateQuiz,
      }}
      secondaryActions={[
        {
          content: "View analytics",
          onAction: handleViewAnalytics,
        },
      ]}
    >
      <BlockStack gap="600">
        {/* Statistics Cards Row */}
        <InlineStack gap="400" align="start" wrap={false}>
          <div style={{ flex: 1 }}>
            <StatCard
              label="Attributed Revenue"
              value={stats.revenue.value}
              trend={stats.revenue.trend}
              up={stats.revenue.up}
              borderColor="var(--p-color-bg-fill-success)"
            />
          </div>
          <div style={{ flex: 1 }}>
            <StatCard
              label="Quiz Completions"
              value={stats.completions.value}
              trend={stats.completions.trend}
              up={stats.completions.up}
              borderColor="var(--p-color-bg-fill-info)"
            />
          </div>
          <div style={{ flex: 1 }}>
            <StatCard
              label="Conversion Rate"
              value={stats.conversionRate.value}
              trend={stats.conversionRate.trend}
              up={stats.conversionRate.up}
              borderColor="var(--p-color-text-emphasis)"
            />
          </div>
          <div style={{ flex: 1 }}>
            <StatCard
              label="Emails Captured"
              value={stats.emailsCaptured.value}
              trend={stats.emailsCaptured.trend}
              up={stats.emailsCaptured.up}
              borderColor="var(--p-color-bg-fill-caution)"
            />
          </div>
        </InlineStack>

        {/* Setup Checklist Banner */}
        <SetupChecklist onFinish={handleFinishSetup} />

        <Divider />

        {/* Quiz List Table */}
        <Layout>
          <Layout.Section>
            <Card padding="0">
              <BlockStack>
                <Box padding="400">
                  <Text as="h2" variant="headingMd">
                    Your Quizzes
                  </Text>
                </Box>
                <IndexTable
                  resourceName={resourceName}
                  itemCount={quizzes.length}
                  selectedItemsCount={
                    allResourcesSelected ? "All" : selectedResources.length
                  }
                  onSelectionChange={handleSelectionChange}
                  headings={[
                    { title: "Quiz" },
                    { title: "Status" },
                    { title: "Questions", alignment: "end" },
                    { title: "Completions", alignment: "end" },
                    { title: "Conv. Rate", alignment: "end" },
                    { title: "Revenue", alignment: "end" },
                    { title: "Updated" },
                    { title: "Actions" },
                  ]}
                >
                  {rowMarkup}
                </IndexTable>
              </BlockStack>
            </Card>
          </Layout.Section>
        </Layout>
      </BlockStack>
    </Page>
  );
}

export const headers: HeadersFunction = (headersArgs) => {
  return boundary.headers(headersArgs);
};

