import { useState, useCallback, useEffect } from "react";
import { json } from "react-router";
import type {
  ActionFunctionArgs,
  HeadersFunction,
  LoaderFunctionArgs,
} from "react-router";
import { useLoaderData, useNavigate, useSubmit } from "react-router";
import {
  Page,
  Layout,
  Card,
  Text,
  InlineStack,
  BlockStack,
  Badge,
  Button,
  Box,
  Divider,
  IndexTable,
  Modal,
  EmptyState,
  useIndexResourceState,
  ButtonGroup,
  SkeletonPage,
  SkeletonBodyText,
} from "@shopify/polaris";
import { useAppBridge } from "@shopify/app-bridge-react";
import { authenticate } from "../shopify.server";
import { boundary } from "@shopify/shopify-app-react-router/server";
import { getQuizzes, deleteQuiz } from "../services/quiz.server";
import db from "../db.server";

// --- Types ---

type BadgeTone = "success" | "attention" | "warning" | undefined;

// --- Status helpers ---

const statusToneMap: Record<string, BadgeTone> = {
  active: "success",
  draft: "attention",
  paused: "warning",
  archived: undefined,
};

function formatStatus(status: string): string {
  return status.charAt(0).toUpperCase() + status.slice(1);
}

function formatQuizType(type: string): string {
  return type
    .split("-")
    .map((word) => word.charAt(0).toUpperCase() + word.slice(1))
    .join(" ");
}

// --- Templates (static) ---

const templates = [
  {
    id: "skincare",
    name: "Skincare Finder",
    emoji: "\uD83E\uDDF4",
    category: "Beauty, Wellness",
    questions: 5,
    types: "Single choice, Image choice, Multiple select, Slider, Email capture",
    badge: "Popular" as const,
  },
  {
    id: "supplement",
    name: "Supplement Advisor",
    emoji: "\uD83D\uDC8A",
    category: "Health, Fitness",
    questions: 4,
    types: "Single choice, Yes/No, Multiple select, Email capture",
    badge: "New" as const,
  },
  {
    id: "style",
    name: "Style Finder",
    emoji: "\uD83D\uDC57",
    category: "Apparel, Fashion",
    questions: 4,
    types: "Image choice, Single choice, Dropdown, Email capture",
    badge: null,
  },
  {
    id: "haircare",
    name: "Hair Care Match",
    emoji: "\uD83D\uDC87",
    category: "Hair, Beauty",
    questions: 4,
    types: "Single choice, Dropdown, Slider, Email capture",
    badge: null,
  },
  {
    id: "fitness",
    name: "Fitness Advisor",
    emoji: "\uD83C\uDFCB\uFE0F",
    category: "Sports, Health",
    questions: 5,
    types: "Single choice, Multiple select, Slider, Yes/No, Email capture",
    badge: null,
  },
  {
    id: "blank",
    name: "Start from blank",
    emoji: "\u2795",
    category: "Custom",
    questions: 0,
    types: "Manual",
    badge: null,
  },
];

const progressSteps = [
  "Reading product catalogue...",
  "Generating questions & answers...",
  "Mapping products to answers...",
  "Finalising your quiz...",
];

// --- Loader ---

export const loader = async ({ request }: LoaderFunctionArgs) => {
  const { session } = await authenticate.admin(request);
  try {
    const quizzes = await getQuizzes(session.shop);
    return json({ quizzes });
  } catch (error) {
    throw json({ error: "Failed to load quizzes" }, { status: 500 });
  }
};

// --- Action ---

export const action = async ({ request }: ActionFunctionArgs) => {
  const { session } = await authenticate.admin(request);
  const formData = await request.formData();
  const intent = formData.get("intent") as string;
  const id = formData.get("id") as string;

  try {
    if (intent === "archive") {
      const quiz = await db.quiz.findFirst({
        where: { id, shop: session.shop },
      });
      if (!quiz) {
        return json({ error: "Quiz not found or access denied" }, { status: 404 });
      }
      await db.quiz.update({
        where: { id },
        data: { status: "archived" },
      });
      return json({ success: true, message: "Quiz archived" });
    }

    if (intent === "delete") {
      await deleteQuiz(id, session.shop);
      return json({ success: true, message: "Quiz deleted" });
    }

    return json({ error: "Unknown intent" }, { status: 400 });
  } catch (error) {
    return json({ error: "Action failed" }, { status: 500 });
  }
};

// --- Hydrate Fallback (skeleton) ---

export function HydrateFallback() {
  return (
    <SkeletonPage title="My Quizzes" primaryAction>
      <BlockStack gap="600">
        <Card>
          <SkeletonBodyText lines={8} />
        </Card>
      </BlockStack>
    </SkeletonPage>
  );
}

// --- Components ---

function TemplateCard({
  template,
  onSelect,
}: {
  template: (typeof templates)[0];
  onSelect: (id: string) => void;
}) {
  const badgeTone =
    template.badge === "Popular"
      ? "success"
      : template.badge === "New"
        ? "info"
        : undefined;

  return (
    <div
      style={{
        cursor: "pointer",
        border: "1px solid var(--p-color-border)",
        borderRadius: "var(--p-border-radius-300)",
        padding: "16px",
        transition: "box-shadow 0.15s ease",
        height: "100%",
      }}
      onClick={() => onSelect(template.id)}
      onMouseEnter={(e) => {
        (e.currentTarget as HTMLElement).style.boxShadow =
          "0 0 0 2px var(--p-color-border-emphasis)";
      }}
      onMouseLeave={(e) => {
        (e.currentTarget as HTMLElement).style.boxShadow = "none";
      }}
      role="button"
      tabIndex={0}
      onKeyDown={(e) => {
        if (e.key === "Enter" || e.key === " ") {
          e.preventDefault();
          onSelect(template.id);
        }
      }}
    >
      <BlockStack gap="300">
        <InlineStack align="space-between" blockAlign="start">
          <Text as="span" variant="headingXl">
            {template.emoji}
          </Text>
          {template.badge && (
            <Badge tone={badgeTone}>{template.badge}</Badge>
          )}
        </InlineStack>
        <BlockStack gap="100">
          <Text as="p" variant="headingSm" fontWeight="semibold">
            {template.name}
          </Text>
          <InlineStack gap="100">
            {template.category.split(", ").map((cat) => (
              <Badge key={cat} tone="info">
                {cat}
              </Badge>
            ))}
          </InlineStack>
        </BlockStack>
        <Text as="p" variant="bodySm" tone="subdued">
          {template.questions === 0
            ? "No pre-built questions"
            : `${template.questions} questions`}
        </Text>
      </BlockStack>
    </div>
  );
}

function AIGenerationOverlay({
  onComplete,
}: {
  onComplete: () => void;
}) {
  const [currentStep, setCurrentStep] = useState(0);
  const [completedSteps, setCompletedSteps] = useState<number[]>([]);

  useEffect(() => {
    const timers: ReturnType<typeof setTimeout>[] = [];

    progressSteps.forEach((_, index) => {
      const timer = setTimeout(() => {
        setCurrentStep(index);
        if (index > 0) {
          setCompletedSteps((prev) => [...prev, index - 1]);
        }
      }, index * 750);
      timers.push(timer);
    });

    // Mark last step complete and navigate
    const finalTimer = setTimeout(() => {
      setCompletedSteps((prev) => [...prev, progressSteps.length - 1]);
    }, progressSteps.length * 750);
    timers.push(finalTimer);

    const navTimer = setTimeout(() => {
      onComplete();
    }, progressSteps.length * 750 + 500);
    timers.push(navTimer);

    return () => timers.forEach(clearTimeout);
  }, [onComplete]);

  return (
    <div
      style={{
        position: "fixed",
        inset: 0,
        zIndex: 9999,
        background: "rgba(255, 255, 255, 0.97)",
        display: "flex",
        alignItems: "center",
        justifyContent: "center",
      }}
    >
      <div style={{ textAlign: "center", maxWidth: 420 }}>
        <div
          style={{
            width: 64,
            height: 64,
            margin: "0 auto 24px",
            border: "4px solid var(--p-color-border)",
            borderTopColor: "var(--p-color-border-emphasis)",
            borderRadius: "50%",
            animation: "quizsnap-spin 0.8s linear infinite",
          }}
        />
        <style>
          {`@keyframes quizsnap-spin { to { transform: rotate(360deg); } }`}
        </style>
        <BlockStack gap="200">
          <Text as="p" variant="headingLg" fontWeight="bold">
            Building your quiz with AI...
          </Text>
          <Text as="p" variant="bodySm" tone="subdued">
            This usually takes a few seconds
          </Text>
        </BlockStack>
        <div style={{ marginTop: 32, textAlign: "left" }}>
          <BlockStack gap="300">
            {progressSteps.map((step, index) => {
              const isCompleted = completedSteps.includes(index);
              const isCurrent = currentStep === index && !isCompleted;
              return (
                <InlineStack key={index} gap="300" blockAlign="center">
                  <div
                    style={{
                      width: 24,
                      height: 24,
                      borderRadius: "50%",
                      display: "flex",
                      alignItems: "center",
                      justifyContent: "center",
                      fontSize: 14,
                      background: isCompleted
                        ? "var(--p-color-bg-fill-success)"
                        : isCurrent
                          ? "var(--p-color-bg-fill-emphasis)"
                          : "var(--p-color-bg-surface-secondary)",
                      color: isCompleted || isCurrent ? "#fff" : "var(--p-color-text-subdued)",
                      flexShrink: 0,
                    }}
                  >
                    {isCompleted ? "\u2713" : index + 1}
                  </div>
                  <Text
                    as="p"
                    variant="bodyMd"
                    tone={isCompleted ? "success" : isCurrent ? undefined : "subdued"}
                    fontWeight={isCurrent ? "semibold" : "regular"}
                  >
                    {step}
                  </Text>
                </InlineStack>
              );
            })}
          </BlockStack>
        </div>
      </div>
    </div>
  );
}

// --- Main Page ---

export default function MyQuizzes() {
  const { quizzes } = useLoaderData<typeof loader>();
  const navigate = useNavigate();
  const submit = useSubmit();
  const shopify = useAppBridge();

  const [modalOpen, setModalOpen] = useState(false);
  const [showAIOverlay, setShowAIOverlay] = useState(false);
  const [selectedTemplate, setSelectedTemplate] = useState<string | null>(null);

  const showEmptyState = quizzes.length === 0;

  const handleOpenModal = useCallback(() => {
    setModalOpen(true);
  }, []);

  const handleCloseModal = useCallback(() => {
    setModalOpen(false);
  }, []);

  const handleSelectTemplate = useCallback(
    (templateId: string) => {
      setSelectedTemplate(templateId);
      setModalOpen(false);

      if (templateId === "blank") {
        navigate("/app/quizzes/new");
      } else {
        setShowAIOverlay(true);
      }
    },
    [navigate],
  );

  const handleAIComplete = useCallback(() => {
    setShowAIOverlay(false);
    shopify.toast.show("Quiz created successfully!");
    navigate(`/app/quizzes/new?template=${selectedTemplate}`);
  }, [navigate, selectedTemplate, shopify]);

  const handleEditQuiz = useCallback(
    (id: string) => {
      navigate(`/app/quizzes/${id}`);
    },
    [navigate],
  );

  const handlePreviewQuiz = useCallback(
    (id: string) => {
      navigate(`/app/quizzes/${id}/preview`);
    },
    [navigate],
  );

  const handleArchiveQuiz = useCallback(
    (id: string) => {
      const formData = new FormData();
      formData.append("intent", "archive");
      formData.append("id", id);
      submit(formData, { method: "POST" });
      shopify.toast.show("Quiz archived");
    },
    [submit, shopify],
  );

  const resourceName = { singular: "quiz", plural: "quizzes" };
  const { selectedResources, allResourcesSelected, handleSelectionChange } =
    useIndexResourceState(quizzes);

  const rowMarkup = quizzes.map(
    (
      quiz: {
        id: string;
        title: string;
        type: string;
        status: string;
        completions: number;
        updatedAt: Date | string;
        _count: { questions: number; responses: number };
      },
      index: number,
    ) => (
      <IndexTable.Row
        id={quiz.id}
        key={quiz.id}
        selected={selectedResources.includes(quiz.id)}
        position={index}
      >
        <IndexTable.Cell>
          <InlineStack gap="300" blockAlign="center">
            <Text as="span" variant="headingMd">
              {"📊"}
            </Text>
            <BlockStack gap="050">
              <Text as="span" variant="bodyMd" fontWeight="semibold">
                {quiz.title}
              </Text>
              <Text as="span" variant="bodySm" tone="subdued">
                {formatQuizType(quiz.type)}
              </Text>
            </BlockStack>
          </InlineStack>
        </IndexTable.Cell>
        <IndexTable.Cell>
          <Badge tone={statusToneMap[quiz.status]}>
            {formatStatus(quiz.status)}
          </Badge>
        </IndexTable.Cell>
        <IndexTable.Cell>
          <Text as="span" variant="bodyMd" alignment="end">
            {quiz._count.questions}
          </Text>
        </IndexTable.Cell>
        <IndexTable.Cell>
          <Text as="span" variant="bodyMd" alignment="end">
            {quiz.completions.toLocaleString()}
          </Text>
        </IndexTable.Cell>
        <IndexTable.Cell>
          <Text as="span" variant="bodyMd" alignment="end">
            {"—"}
          </Text>
        </IndexTable.Cell>
        <IndexTable.Cell>
          <Text as="span" variant="bodyMd" alignment="end">
            {"—"}
          </Text>
        </IndexTable.Cell>
        <IndexTable.Cell>
          <Text as="span" variant="bodySm" tone="subdued">
            {new Date(quiz.updatedAt).toLocaleDateString("en-US", {
              month: "short",
              day: "numeric",
              year: "numeric",
            })}
          </Text>
        </IndexTable.Cell>
        <IndexTable.Cell>
          <ButtonGroup>
            <Button size="slim" onClick={() => handleEditQuiz(quiz.id)}>
              Edit
            </Button>
            <Button
              size="slim"
              variant="plain"
              onClick={() => handlePreviewQuiz(quiz.id)}
            >
              Preview
            </Button>
            <Button
              size="slim"
              variant="plain"
              tone="critical"
              onClick={() => handleArchiveQuiz(quiz.id)}
            >
              Archive
            </Button>
          </ButtonGroup>
        </IndexTable.Cell>
      </IndexTable.Row>
    ),
  );

  return (
    <>
      {showAIOverlay && <AIGenerationOverlay onComplete={handleAIComplete} />}

      <Page
        title="My Quizzes"
        primaryAction={{
          content: "+ Create quiz",
          onAction: handleOpenModal,
        }}
      >
        <BlockStack gap="600">
          {showEmptyState ? (
            <Card>
              <EmptyState
                heading="Create your first quiz"
                action={{
                  content: "Create quiz",
                  onAction: handleOpenModal,
                }}
                image="https://cdn.shopify.com/s/files/1/0262/4071/2726/files/emptystate-files.png"
              >
                <p>
                  Build product recommendation quizzes that help your customers
                  find the perfect product and boost your sales.
                </p>
              </EmptyState>
            </Card>
          ) : (
            <Layout>
              <Layout.Section>
                <Card padding="0">
                  <BlockStack>
                    <Box padding="400">
                      <InlineStack align="space-between" blockAlign="center">
                        <Text as="h2" variant="headingMd">
                          All Quizzes
                        </Text>
                        <Text as="p" variant="bodySm" tone="subdued">
                          {quizzes.length} {quizzes.length === 1 ? "quiz" : "quizzes"}
                        </Text>
                      </InlineStack>
                    </Box>
                    <IndexTable
                      resourceName={resourceName}
                      itemCount={quizzes.length}
                      selectedItemsCount={
                        allResourcesSelected
                          ? "All"
                          : selectedResources.length
                      }
                      onSelectionChange={handleSelectionChange}
                      headings={[
                        { title: "Quiz" },
                        { title: "Status" },
                        { title: "Questions", alignment: "end" },
                        { title: "Completions", alignment: "end" },
                        { title: "Conv. Rate", alignment: "end" },
                        { title: "Revenue", alignment: "end" },
                        { title: "Updated" },
                        { title: "Actions" },
                      ]}
                    >
                      {rowMarkup}
                    </IndexTable>
                  </BlockStack>
                </Card>
              </Layout.Section>
            </Layout>
          )}
        </BlockStack>
      </Page>

      <Modal open={modalOpen} onClose={handleCloseModal}>
        <Box padding="400">
          <BlockStack gap="400">
            <Text as="h2" variant="headingLg" fontWeight="bold">
              Choose a template
            </Text>
            <Text as="p" variant="bodyMd" tone="subdued">
              Pick a pre-built quiz template or start from scratch
            </Text>
            <Divider />
            <div
              style={{
                display: "grid",
                gridTemplateColumns: "repeat(3, 1fr)",
                gap: "16px",
              }}
            >
              {templates.map((template) => (
                <TemplateCard
                  key={template.id}
                  template={template}
                  onSelect={handleSelectTemplate}
                />
              ))}
            </div>
          </BlockStack>
        </Box>
      </Modal>
    </>
  );
}

export const headers: HeadersFunction = (headersArgs) => {
  return boundary.headers(headersArgs);
};

