              />
              <TextField
                label="Maximum score"
                type="number"
                value={maxScore}
                onChange={setMaxScore}
                autoComplete="off"
                placeholder="100"
              />
            </FormLayout.Group>
          )}

          {type === "tag-match" && (
            <TextField
              label="Match tags (comma-separated)"
              value={matchTags}
              onChange={setMatchTags}
              autoComplete="off"
              placeholder="skincare, sensitive, dry"
              helpText="Shoppers whose answers match these product tags will see this result page."
            />
          )}

          <Select
            label="Product display layout"
            options={layoutOptions}
            value={layout}
            onChange={setLayout}
          />

          <Select
            label="Product limit"
            options={productLimitOptions}
            value={productLimit}
            onChange={setProductLimit}
          />

          <Checkbox
            label="Show discount"
            checked={showDiscount}
            onChange={setShowDiscount}
            helpText="Display a discount code on this result page."
          />

          {showDiscount && (
            <>
              <FormLayout.Group>
                <Select
                  label="Discount type"
                  options={discountTypeOptions}
                  value={discountType}
                  onChange={setDiscountType}
                />
                <TextField
                  label="Discount value"
                  type="number"
                  value={discountValue}
                  onChange={setDiscountValue}
                  autoComplete="off"
                  placeholder={discountType === "percentage" ? "10" : "5.00"}
                  suffix={discountType === "percentage" ? "%" : "$"}
                />
              </FormLayout.Group>
              <TextField
                label="Discount code"
                value={discountCode}
                onChange={setDiscountCode}
                autoComplete="off"
                placeholder="QUIZSNAP10"
                helpText="The actual Shopify discount code shoppers will apply at checkout."
              />
            </>
          )}

          <Divider />

          <TextField
            label="CTA button text"
            value={ctaText}
            onChange={setCtaText}
            autoComplete="off"
            placeholder="Shop Now"
          />
          <TextField
            label="CTA button URL"
            value={ctaUrl}
            onChange={setCtaUrl}
            autoComplete="off"
