                      position={index}
                      selected={page.id === selectedPageId}
                      onClick={() => setSelectedPageId(page.id)}
                    >
                      <IndexTable.Cell>
                        <BlockStack gap="050">
                          <InlineStack gap="200" blockAlign="center">
                            <Text as="p" variant="bodySm" fontWeight="semibold" truncate>
                              {page.title}
                            </Text>
                            <Badge tone={typeBadgeTone(page.type)}>
                              {typeBadgeLabel(page.type)}
                            </Badge>
                          </InlineStack>
                          <Text as="p" variant="bodySm" tone="subdued">
                            Position {page.position + 1} · {page.layout} ·{" "}
                            {page.productLimit} products
                          </Text>
                        </BlockStack>
                      </IndexTable.Cell>
                    </IndexTable.Row>
                  ))}
                </IndexTable>
                <Divider />
                <Box padding="400">
                  <Button
                    fullWidth
                    onClick={() => setCreateModalOpen(true)}
                    loading={isMutating}
                  >
                    + Add result page
                  </Button>
                </Box>
              </Card>
            </Layout.Section>

            {/* Right panel — edit form */}
            <Layout.Section>
              {selectedPage ? (
                <EditPanel
                  key={selectedPage.id}
                  page={selectedPage}
                  onDelete={handleDeleteRequest}
                  isSaving={isMutating}
                />
              ) : (
                <Card>
                  <Box padding="600">
                    <Text as="p" variant="bodyMd" tone="subdued">
                      Select a result page from the sidebar to edit it.
                    </Text>
                  </Box>
                </Card>
              )}
            </Layout.Section>
          </Layout>
        )}
      </Page>

      {/* Create result page modal */}
      <Modal
        open={createModalOpen}
        onClose={() => {
          setCreateModalOpen(false);
          setNewPageTitle("");
          setNewPageType("default");
        }}
        title="Add result page"
        primaryAction={{
          content: "Create",
          onAction: handleCreateConfirm,
          loading: isMutating,
        }}
        secondaryActions={[
          {
            content: "Cancel",
            onAction: () => {
              setCreateModalOpen(false);
              setNewPageTitle("");
              setNewPageType("default");
            },
          },
        ]}
