    26→};
    27→
    28→export const action = async ({ request }: ActionFunctionArgs) => {
    29→  const { session } = await authenticate.admin(request);
    30→  const formData = await request.formData();
    31→  const title = String(formData.get("title") ?? "").trim();
    32→  const type = String(formData.get("type") ?? "product-recommendation");
    33→  const description = String(formData.get("description") ?? "").trim() || null;
    34→
    35→  if (!title) {
    36→    return { error: "Quiz title is required" };
    37→  }
    38→
    39→  try {
    40→    // Check plan limits
    41→    const count = await db.quiz.count({
    42→      where: { shop: session.shop, status: { not: "archived" } },
    43→    });
    44→
    45→    const sub = await db.subscription.findUnique({
    46→      where: { shop: session.shop },
    47→      select: { planId: true },
    48→    });
    49→
    50→    const planId = sub?.planId ?? "free";
    51→    const limits: Record<string, number> = {
    52→      free: 1,
    53→      starter: 5,
    54→      pro: 999,
    55→      enterprise: 999,
    56→    };
    57→    const limit = limits[planId] ?? 1;
    58→
    59→    if (count >= limit) {
    60→      return {
    61→        error: `You've reached the ${limit}-quiz limit for your ${planId} plan. Please upgrade to create more quizzes.`,
    62→      };
    63→    }
    64→
    65→    // Generate unique slug
    66→    const base =
    67→      title
    68→        .toLowerCase()
    69→        .replace(/[^a-z0-9\s-]/g, "")
    70→        .replace(/\s+/g, "-")
    71→        .replace(/-+/g, "-")
    72→        .replace(/^-|-$/g, "") || "quiz";
    73→
    74→    let slug = base;
    75→    let counter = 0;
    76→    while (await db.quiz.findFirst({ where: { shop: session.shop, slug } })) {
    77→      counter++;
    78→      slug = `${base}-${counter}`;
    79→    }
    80→
    81→    const quiz = await db.quiz.create({
    82→      data: { shop: session.shop, title, slug, type, description },
    83→    });
    84→
    85→    return redirect(`/app/quizzes/${quiz.id}`);
    86→  } catch (error) {
    87→    console.error("Create quiz error:", error);
    88→    return { error: "Failed to create quiz. Please try again." };
    89→  }
    90→};
