   388→  );
   389→  const [discountValue, setDiscountValue] = useState(
   390→    page.discountValue !== null ? String(page.discountValue) : ""
   391→  );
   392→  const [discountCode, setDiscountCode] = useState(page.discountCode ?? "");
   393→  const [ctaText, setCtaText] = useState(page.ctaText ?? "");
   394→  const [ctaUrl, setCtaUrl] = useState(page.ctaUrl ?? "");
   395→  const shopify = useAppBridge();
   396→
   397→  // Reset local state when page selection changes
   398→  useEffect(() => {
   399→    setTitle(page.title);
   400→    setDescription(page.description ?? "");
   401→    setType(page.type);
   402→    setMinScore(page.minScore !== null ? String(page.minScore) : "");
   403→    setMaxScore(page.maxScore !== null ? String(page.maxScore) : "");
   404→    setMatchTags(page.matchTags.join(", "));
