   414→
   415→  // Toast from fetcher (inline save)
   416→  useEffect(() => {
   417→    if (!fetcher.data) return;
   418→    if ("success" in fetcher.data && fetcher.data.success && "message" in fetcher.data) {
   419→      shopify.toast.show(String(fetcher.data.message), { duration: 3000 });
   420→    } else if ("error" in fetcher.data && fetcher.data.error) {
