   645→export default function ResultPagesEditor() {
   646→  const loaderResult = useLoaderData<typeof loader>() as unknown as LoaderData;
   647→  const { quiz, resultPages } = loaderResult;
   648→  const actionData = useActionData<typeof action>() as ActionResponse | undefined;
   649→  const fetcher = useFetcher<typeof action>() as {
   650→    data: ActionResponse | undefined;
   651→    state: "idle" | "loading" | "submitting";
   652→    submit: (data: FormData, options: { method: string }) => void;
   653→  };
   654→  const shopify = useAppBridge();
   655→
   656→  const [selectedPageId, setSelectedPageId] = useState<string | null>(
   657→    resultPages.length > 0 ? resultPages[0].id : null
   658→  );
   659→  const [deleteModalOpen, setDeleteModalOpen] = useState(false);
   660→  const [pendingDeleteId, setPendingDeleteId] = useState<string | null>(null);
   661→  const [createModalOpen, setCreateModalOpen] = useState(false);
   662→  const [newPageTitle, setNewPageTitle] = useState("");
   663→  const [newPageType, setNewPageType] = useState("default");
