import { Card, BlockStack, Text, Button, Badge } from "@shopify/polaris";
import type { PlanId } from "~/utils/constants";

interface PlanGateProps {
  requiredPlan: PlanId;
  currentPlan: PlanId;
  featureName: string;
  children: React.ReactNode;
}

const PLAN_ORDER: PlanId[] = ["free", "starter", "pro", "enterprise"];

export function PlanGate({
  requiredPlan,
  currentPlan,
  featureName,
  children,
}: PlanGateProps) {
  const hasAccess =
    PLAN_ORDER.indexOf(currentPlan) >= PLAN_ORDER.indexOf(requiredPlan);

  if (hasAccess) return <>{children}</>;

  const planName =
    requiredPlan.charAt(0).toUpperCase() + requiredPlan.slice(1);

  return (
    <Card>
      <BlockStack gap="400">
        <BlockStack gap="200">
          <Badge tone="warning">{planName} plan required</Badge>
          <Text variant="headingMd" as="h3">
            {featureName}
          </Text>
          <Text as="p" tone="subdued">
            Upgrade to the {planName} plan to access{" "}
            {featureName.toLowerCase()}.
          </Text>
        </BlockStack>
        <Button url="/app/billing" variant="primary">
          Upgrade to {planName}
        </Button>
      </BlockStack>
    </Card>
  );
}

import { useState, useEffect, useCallback } from "react";
import type { ActionFunctionArgs, HeadersFunction, LoaderFunctionArgs } from "react-router";
import { useLoaderData, useActionData, useNavigation, Form } from "react-router";
import {
  Page,
  Layout,
  Card,
  Text,
  InlineStack,
  BlockStack,
  Button,
  Badge,
  TextField,
  Banner,
  Modal,
  Divider,
  SkeletonPage,
  SkeletonBodyText,
  Box,
} from "@shopify/polaris";
import { useAppBridge } from "@shopify/app-bridge-react";
import { data } from "react-router";
import { authenticate } from "../shopify.server";
import { boundary } from "@shopify/shopify-app-react-router/server";
import db from "../db.server";

// ─── Types ────────────────────────────────────────────────────────────────────

type Provider = "klaviyo" | "mailchimp" | "omnisend" | "custom-webhook";

interface IntegrationRecord {
  id: string;
  provider: Provider;
  apiKey: string;
  listId: string | null;
  isActive: boolean;
}

interface ProviderConfig {
  id: Provider;
  name: string;
  emoji: string;
  description: string;
  apiKeyLabel: string;
  apiKeyPlaceholder: string;
  listIdLabel: string | null;
  listIdPlaceholder: string | null;
  docsUrl: string;
  requiredPlan: "starter" | "pro";
}

// ─── Provider definitions ─────────────────────────────────────────────────────

const PROVIDERS: ProviderConfig[] = [
  {
    id: "klaviyo",
    name: "Klaviyo",
    emoji: "📧",
    description:
      "Sync quiz completions to Klaviyo — send answer properties, segment contacts by quiz result, and trigger email flows automatically.",
    apiKeyLabel: "Private API key",
    apiKeyPlaceholder: "pk_••••••••••••••••••••••••••••••••",
    listIdLabel: "List ID (optional)",
    listIdPlaceholder: "e.g. AbCdEf",
    docsUrl: "https://help.klaviyo.com/hc/en-us/articles/115005062267",
    requiredPlan: "starter",
  },
  {
    id: "mailchimp",
    name: "Mailchimp",
    emoji: "🐒",
    description:
      "Add quiz respondents to a Mailchimp audience, tag them by result, and trigger automated email journeys.",
    apiKeyLabel: "API key",
    apiKeyPlaceholder: "••••••••••••••••••••••••••••••••-us1",
    listIdLabel: "Audience ID",
    listIdPlaceholder: "e.g. a1b2c3d4e5",
    docsUrl: "https://mailchimp.com/developer/marketing/guides/quick-start/",
    requiredPlan: "starter",
  },
  {
    id: "omnisend",
    name: "Omnisend",
    emoji: "📬",
    description:
      "Push quiz completion events to Omnisend for SMS and email automations, contact tagging, and segmentation.",
    apiKeyLabel: "API key",
    apiKeyPlaceholder: "••••••••••••••••••••••••••••••••••••••••",
    listIdLabel: null,
    listIdPlaceholder: null,
    docsUrl: "https://api-docs.omnisend.com/",
    requiredPlan: "pro",
  },
  {
    id: "custom-webhook",
    name: "Custom Webhook",
    emoji: "🔗",
    description:
      "Send quiz completion payloads to any URL via HTTP POST. Works with Zapier, Make, n8n, and any custom endpoint.",
    apiKeyLabel: "Webhook URL",
    apiKeyPlaceholder: "https://hooks.zapier.com/hooks/catch/••••••/••••••/",
    listIdLabel: "Secret header value (optional)",
    listIdPlaceholder: "Used as X-QuizSnap-Secret header",
    docsUrl: "https://zapier.com/apps/webhook/integrations",
    requiredPlan: "pro",
  },
];

// ─── Loader ───────────────────────────────────────────────────────────────────

export const loader = async ({ request }: LoaderFunctionArgs) => {
  const { session } = await authenticate.admin(request);

  try {
    const [integrations, sub] = await Promise.all([
      db.emailIntegration.findMany({
        where: { shop: session.shop },
        select: {
          id: true,
          provider: true,
          apiKey: true,
          listId: true,
          isActive: true,
        },
        orderBy: { createdAt: "asc" },
      }),
      db.subscription.findUnique({
        where: { shop: session.shop },
        select: { planId: true },
      }),
    ]);

    const planId = sub?.planId ?? "free";

    // Mask API keys for display — keep first 4 and last 4 chars visible
    const masked = integrations.map((i) => ({
      ...i,
      provider: i.provider as Provider,
      apiKey:
        i.apiKey.length > 8
          ? `${i.apiKey.slice(0, 4)}${"•".repeat(Math.max(0, i.apiKey.length - 8))}${i.apiKey.slice(-4)}`
          : "••••••••",
    }));

    return { integrations: masked as IntegrationRecord[], planId };
  } catch (error) {
    console.error("Integrations loader error:", error);
    throw data({ error: "Failed to load integrations" }, { status: 500 });
  }
};

// ─── Action ───────────────────────────────────────────────────────────────────

export const action = async ({ request }: ActionFunctionArgs) => {
  const { session } = await authenticate.admin(request);
  const formData = await request.formData();
  const intent = String(formData.get("intent") ?? "");
  const provider = String(formData.get("provider") ?? "") as Provider;

  const validProviders: Provider[] = [
    "klaviyo",
    "mailchimp",
    "omnisend",
    "custom-webhook",
  ];
  if (!validProviders.includes(provider)) {
    return data({ error: "Invalid provider" }, { status: 400 });
  }

  try {
    if (intent === "connect") {
      const apiKey = String(formData.get("apiKey") ?? "").trim();
      const listId = String(formData.get("listId") ?? "").trim() || null;

      if (!apiKey) {
        return data(
          { error: "API key is required", provider },
          { status: 400 },
        );
      }

      // Plan gate — check before writing
      const sub = await db.subscription.findUnique({
        where: { shop: session.shop },
        select: { planId: true },
      });
      const planId = sub?.planId ?? "free";
      const config = PROVIDERS.find((p) => p.id === provider);

      if (!config) {
        return data({ error: "Unknown provider" }, { status: 400 });
      }

      const planOrder = ["free", "starter", "pro", "enterprise"];
      const currentIdx = planOrder.indexOf(planId);
      const requiredIdx = planOrder.indexOf(config.requiredPlan);

      if (currentIdx < requiredIdx) {
        return data(
          {
            error: `${config.name} requires the ${config.requiredPlan} plan or higher. Please upgrade.`,
            provider,
          },
          { status: 403 },
        );
      }

      await db.emailIntegration.upsert({
        where: { shop_provider: { shop: session.shop, provider } },
        create: {
          shop: session.shop,
          provider,
          apiKey,
          listId,
          isActive: true,
        },
        update: { apiKey, listId, isActive: true },
      });

      const providerName = config.name;
      return {
        success: true,
        message: `${providerName} connected successfully!`,
        provider,
      };
    }

    if (intent === "disconnect") {
      await db.emailIntegration.deleteMany({
        where: { shop: session.shop, provider },
      });

      const providerName =
        PROVIDERS.find((p) => p.id === provider)?.name ?? provider;
      return {
        success: true,
        message: `${providerName} disconnected`,
        provider,
      };
    }

    if (intent === "toggle") {
      const existing = await db.emailIntegration.findUnique({
        where: { shop_provider: { shop: session.shop, provider } },
      });
      if (!existing) {
        return data({ error: "Integration not found" }, { status: 404 });
      }
      await db.emailIntegration.update({
        where: { shop_provider: { shop: session.shop, provider } },
        data: { isActive: !existing.isActive },
      });
      return {
        success: true,
        message: existing.isActive ? "Integration paused" : "Integration enabled",
        provider,
      };
    }

    return data({ error: "Unknown intent" }, { status: 400 });
  } catch (error) {
    console.error("Integrations action error:", error);
    return data(
      { error: "Action failed. Please try again." },
      { status: 500 },
    );
  }
};

// ─── Component helpers ────────────────────────────────────────────────────────

function PlanGateBanner({
  requiredPlan,
  currentPlan,
}: {
  requiredPlan: string;
  currentPlan: string;
}) {
  const planOrder = ["free", "starter", "pro", "enterprise"];
  const isGated =
    planOrder.indexOf(currentPlan) < planOrder.indexOf(requiredPlan);

  if (!isGated) return null;

  const label = requiredPlan.charAt(0).toUpperCase() + requiredPlan.slice(1);

  return (
    <Banner
      tone="warning"
      title={`${label} plan required`}
      action={{ content: "Upgrade now", url: "/app/billing" }}
    >
      <p>
        Upgrade to the {label} plan or higher to use this integration.
      </p>
    </Banner>
  );
}

interface ConnectModalProps {
  config: ProviderConfig;
  open: boolean;
  onClose: () => void;
  isSubmitting: boolean;
}

function ConnectModal({
  config,
  open,
  onClose,
  isSubmitting,
}: ConnectModalProps) {
  const [apiKey, setApiKey] = useState("");
  const [listId, setListId] = useState("");

  // Reset fields when modal opens
  useEffect(() => {
    if (open) {
      setApiKey("");
      setListId("");
    }
  }, [open]);

  return (
    <Modal
      open={open}
      onClose={onClose}
      title={`Connect ${config.name}`}
      primaryAction={{
        content: "Connect",
        submit: true,
        loading: isSubmitting,
        disabled: !apiKey.trim() || isSubmitting,
      }}
      secondaryActions={[{ content: "Cancel", onAction: onClose }]}
    >
      <Modal.Section>
        <Form method="post">
          <input type="hidden" name="intent" value="connect" />
          <input type="hidden" name="provider" value={config.id} />
          <BlockStack gap="400">
            <Text as="p" variant="bodyMd" tone="subdued">
              {config.description}
            </Text>
            <TextField
              label={config.apiKeyLabel}
              name="apiKey"
              value={apiKey}
              onChange={setApiKey}
              placeholder={config.apiKeyPlaceholder}
              autoComplete="off"
              requiredIndicator
              helpText={
                <span>
                  Find this in your{" "}
                  <a
                    href={config.docsUrl}
                    target="_blank"
                    rel="noopener noreferrer"
                  >
                    {config.name} account settings
                  </a>
                </span>
              }
            />
            {config.listIdLabel && (
              <TextField
                label={config.listIdLabel}
                name="listId"
                value={listId}
                onChange={setListId}
                placeholder={config.listIdPlaceholder ?? ""}
                autoComplete="off"
              />
            )}
          </BlockStack>
        </Form>
      </Modal.Section>
    </Modal>
  );
}

// ─── Main page ────────────────────────────────────────────────────────────────

export default function IntegrationsPage() {
  const { integrations, planId } = useLoaderData<typeof loader>();
  const actionData = useActionData<typeof action>();
  const navigation = useNavigation();
  const shopify = useAppBridge();
  const isSubmitting = navigation.state === "submitting";

  const [openModal, setOpenModal] = useState<Provider | null>(null);

  const connectedMap = new Map(
    integrations.map((i) => [i.provider, i]),
  );

  useEffect(() => {
    if (actionData && "success" in actionData && actionData.success) {
      shopify.toast.show(actionData.message ?? "Done!", { duration: 3000 });
      setOpenModal(null);
    }
    if (actionData && "error" in actionData && actionData.error) {
      shopify.toast.show(actionData.error, { isError: true });
    }
  }, [actionData, shopify]);

  const handleOpenModal = useCallback((provider: Provider) => {
    setOpenModal(provider);
  }, []);

  const handleCloseModal = useCallback(() => {
    setOpenModal(null);
  }, []);

  const connectedCount = integrations.filter((i) => i.isActive).length;

  return (
    <Page
      title="Integrations"
      subtitle="Connect QuizSnap to your email and marketing tools"
    >
      <Layout>
        <Layout.Section>
          <BlockStack gap="500">
            {connectedCount > 0 && (
              <Banner tone="success" title={`${connectedCount} integration${connectedCount > 1 ? "s" : ""} active`}>
                <p>
                  Quiz completions are being synced to your connected
                  providers.
                </p>
              </Banner>
            )}

            {PROVIDERS.map((config) => {
              const connected = connectedMap.get(config.id);
              const isConnected = Boolean(connected);
              const isActive = connected?.isActive ?? false;
              const planOrder = ["free", "starter", "pro", "enterprise"];
              const isGated =
                planOrder.indexOf(planId) <
                planOrder.indexOf(config.requiredPlan);
              const requiredLabel =
                config.requiredPlan.charAt(0).toUpperCase() +
                config.requiredPlan.slice(1);

              return (
                <Card key={config.id}>
                  <BlockStack gap="400">
                    <InlineStack align="space-between" blockAlign="start">
                      <InlineStack gap="300" blockAlign="center">
                        <Text as="span" variant="headingXl">
                          {config.emoji}
                        </Text>
                        <BlockStack gap="100">
                          <InlineStack gap="200" blockAlign="center">
                            <Text
                              as="h3"
                              variant="headingMd"
                              fontWeight="semibold"
                            >
                              {config.name}
                            </Text>
                            {isGated && (
                              <Badge tone="warning">
                                {requiredLabel}+
                              </Badge>
                            )}
                            {isConnected && !isGated && (
                              <Badge
                                tone={isActive ? "success" : "attention"}
                              >
                                {isActive ? "Connected" : "Paused"}
                              </Badge>
                            )}
                          </InlineStack>
                          <Text as="p" variant="bodySm" tone="subdued">
                            {config.description}
                          </Text>
                        </BlockStack>
                      </InlineStack>

                      <InlineStack gap="200">
                        {isGated ? (
                          <Button url="/app/billing" variant="primary">
                            Upgrade to {requiredLabel}
                          </Button>
                        ) : isConnected ? (
                          <>
                            <Form method="post">
                              <input
                                type="hidden"
                                name="intent"
                                value="toggle"
                              />
                              <input
                                type="hidden"
                                name="provider"
                                value={config.id}
                              />
                              <Button
                                submit
                                disabled={isSubmitting}
                                loading={
                                  isSubmitting &&
                                  navigation.formData?.get("provider") ===
                                    config.id &&
                                  navigation.formData?.get("intent") ===
                                    "toggle"
                                }
                              >
                                {isActive ? "Pause" : "Enable"}
                              </Button>
                            </Form>
                            <Form method="post">
                              <input
                                type="hidden"
                                name="intent"
                                value="disconnect"
                              />
                              <input
                                type="hidden"
                                name="provider"
                                value={config.id}
                              />
                              <Button
                                submit
                                tone="critical"
                                disabled={isSubmitting}
                                loading={
                                  isSubmitting &&
                                  navigation.formData?.get("provider") ===
                                    config.id &&
                                  navigation.formData?.get("intent") ===
                                    "disconnect"
                                }
                              >
                                Disconnect
                              </Button>
                            </Form>
                          </>
                        ) : (
                          <Button
                            variant="primary"
                            onClick={() => handleOpenModal(config.id)}
                            disabled={isSubmitting}
                          >
                            Connect
                          </Button>
                        )}
                      </InlineStack>
                    </InlineStack>

                    {isConnected && connected && (
                      <>
                        <Divider />
                        <Box
                          background="bg-surface-secondary"
                          padding="300"
                          borderRadius="200"
                        >
                          <InlineStack gap="600" wrap={false}>
                            <BlockStack gap="050">
                              <Text as="p" variant="bodySm" tone="subdued">
                                {config.apiKeyLabel}
                              </Text>
                              <Text as="p" variant="bodyMd">
                                {connected.apiKey}
                              </Text>
                            </BlockStack>
                            {connected.listId && (
                              <BlockStack gap="050">
                                <Text
                                  as="p"
                                  variant="bodySm"
                                  tone="subdued"
                                >
                                  {config.listIdLabel ?? "List / Group ID"}
                                </Text>
                                <Text as="p" variant="bodyMd">
                                  {connected.listId}
                                </Text>
                              </BlockStack>
                            )}
                          </InlineStack>
                        </Box>
                      </>
                    )}

                    {isGated && (
                      <PlanGateBanner
                        requiredPlan={config.requiredPlan}
                        currentPlan={planId}
                      />
                    )}
                  </BlockStack>
                </Card>
              );
            })}
          </BlockStack>
        </Layout.Section>
      </Layout>

      {/* Connect modals — one per provider */}
      {PROVIDERS.map((config) => (
        <ConnectModal
          key={config.id}
          config={config}
          open={openModal === config.id}
          onClose={handleCloseModal}
          isSubmitting={isSubmitting}
        />
      ))}
    </Page>
  );
}

