                <p>
                  Quiz completions are being synced to your connected
                  providers.
                </p>
              </Banner>
            )}

            {PROVIDERS.map((config) => {
              const connected = connectedMap.get(config.id);
              const isConnected = Boolean(connected);
              const isActive = connected?.isActive ?? false;
              const planOrder = ["free", "starter", "pro", "enterprise"];
              const isGated =
                planOrder.indexOf(planId) <
                planOrder.indexOf(config.requiredPlan);
              const requiredLabel =
                config.requiredPlan.charAt(0).toUpperCase() +
                config.requiredPlan.slice(1);

              return (
                <Card key={config.id}>
                  <BlockStack gap="400">
                    <InlineStack align="space-between" blockAlign="start">
                      <InlineStack gap="300" blockAlign="center">
                        <Text as="span" variant="headingXl">
                          {config.emoji}
                        </Text>
                        <BlockStack gap="100">
                          <InlineStack gap="200" blockAlign="center">
                            <Text
                              as="h3"
                              variant="headingMd"
                              fontWeight="semibold"
                            >
                              {config.name}
                            </Text>
                            {isGated && (
                              <Badge tone="warning">
                                {requiredLabel}+
                              </Badge>
                            )}
                            {isConnected && !isGated && (
                              <Badge
                                tone={isActive ? "success" : "attention"}
                              >
                                {isActive ? "Connected" : "Paused"}
                              </Badge>
                            )}
                          </InlineStack>
                          <Text as="p" variant="bodySm" tone="subdued">
                            {config.description}
                          </Text>
                        </BlockStack>
                      </InlineStack>

                      <InlineStack gap="200">
                        {isGated ? (
                          <Button url="/app/billing" variant="primary">
                            Upgrade to {requiredLabel}
                          </Button>
                        ) : isConnected ? (
                          <>
                            <Form method="post">
                              <input
                                type="hidden"
                                name="intent"
                                value="toggle"
                              />
                              <input
                                type="hidden"
                                name="provider"
                                value={config.id}
                              />
                              <Button
                                submit
                                disabled={isSubmitting}
                                loading={
                                  isSubmitting &&
                                  navigation.formData?.get("provider") ===
                                    config.id &&
                                  navigation.formData?.get("intent") ===
                                    "toggle"
                                }
                              >
                                {isActive ? "Pause" : "Enable"}
                              </Button>
                            </Form>
                            <Form method="post">
                              <input
                                type="hidden"
                                name="intent"
                                value="disconnect"
                              />
                              <input
                                type="hidden"
                                name="provider"
                                value={config.id}
                              />
                              <Button
                                submit
                                tone="critical"
                                disabled={isSubmitting}
                                loading={
                                  isSubmitting &&
                                  navigation.formData?.get("provider") ===
                                    config.id &&
                                  navigation.formData?.get("intent") ===
                                    "disconnect"
                                }
                              >
                                Disconnect
                              </Button>
                            </Form>
                          </>
                        ) : (
                          <Button
                            variant="primary"
                            onClick={() => handleOpenModal(config.id)}
                            disabled={isSubmitting}
                          >
                            Connect
                          </Button>
                        )}
                      </InlineStack>
                    </InlineStack>

                    {isConnected && connected && (
                      <>
                        <Divider />
                        <Box
                          background="bg-surface-secondary"
                          padding="300"
                          borderRadius="200"
                        >
                          <InlineStack gap="600" wrap={false}>
                            <BlockStack gap="050">
                              <Text as="p" variant="bodySm" tone="subdued">
                                {config.apiKeyLabel}
                              </Text>
                              <Text as="p" variant="bodyMd">
                                {connected.apiKey}
                              </Text>
                            </BlockStack>
                            {connected.listId && (
                              <BlockStack gap="050">
                                <Text
                                  as="p"
                                  variant="bodySm"
                                  tone="subdued"
                                >
                                  {config.listIdLabel ?? "List / Group ID"}
                                </Text>
                                <Text as="p" variant="bodyMd">
                                  {connected.listId}
                                </Text>
                              </BlockStack>
                            )}
                          </InlineStack>
                        </Box>
                      </>
                    )}

                    {isGated && (
                      <PlanGateBanner
                        requiredPlan={config.requiredPlan}
                        currentPlan={planId}
                      />
                    )}
                  </BlockStack>
                </Card>
              );
            })}
          </BlockStack>
        </Layout.Section>
      </Layout>

      {/* Connect modals — one per provider */}
      {PROVIDERS.map((config) => (
        <ConnectModal
          key={config.id}
          config={config}
          open={openModal === config.id}
          onClose={handleCloseModal}
          isSubmitting={isSubmitting}
        />
      ))}
    </Page>
  );
}

export function HydrateFallback() {
  return (
    <SkeletonPage title="Integrations">
      <Layout>
        <Layout.Section>
          <BlockStack gap="400">
            <SkeletonBodyText lines={4} />
            <SkeletonBodyText lines={4} />
            <SkeletonBodyText lines={4} />
            <SkeletonBodyText lines={4} />
          </BlockStack>
        </Layout.Section>
      </Layout>
    </SkeletonPage>
  );
}

export const headers: HeadersFunction = (headersArgs) => {
  return boundary.headers(headersArgs);
};

